const accuracy = totalQuestions > 0 ? Math.round(correctAnswers / totalQuestions) * 10;
accuracyEl.textContent = `${accuracy}%`;

// 比较答案（英文）
function compareAnswers(userAnswer, correctAnswer) {
  // 标准化答案：转为小写，去除多余空格
  const normalizedUser = userAnswer.toLowerCase().replace(/\s+/g, '').trim();
  const normalizedCorrect = correctAnswer.toLowerCase().replace(/\s+/g, '').trim();

  // 直接比较
  if (normalizedUser === normalizedCorrect) return true;

  // 检查是否包含斜杠分隔的多个答案
  if (correctAnswer.includes('/')) {
    const alternatives = correctAnswer.split('/');
    for (let of alternatives) {
      if (normalizedUser === alt.toLowerCase().replace(/\s+/g, '').trim()) {
        return true;
      }
    }
  }
}

